import numpy as np
xs = np.logspace(-4, 0, 400)            # singular values after normalization
def band(a, b, c, burn=60, keep=40):    # range the iterates settle into
    x = xs.copy()
    for t in range(burn + keep):
        x = a*x + b*x**3 + c*x**5
        if np.abs(x).max() > 10: return None
        if t == burn: lo, hi = x.min(), x.max()
        if t > burn: lo, hi = min(lo, x.min()), max(hi, x.max())
    return round(float(lo), 3), round(float(hi), 3)
def feasible(a):                        # some (b, c) with band inside [0.7, 1.3]?
    for b in np.arange(-6, -2, 0.02):
        for c in np.arange(0.5, 3, 0.02):
            r = band(a, b, c)
            if r and r[0] >= 0.7 and r[1] <= 1.3:
                return round(float(b), 2), round(float(c), 2), r
    return None
for a in [3.0, 3.5, 3.6, 3.65, 3.7]:
    print("a =", a, "first feasible (b, c, band):", feasible(a))
print("Muon's (3.4445, -4.7750, 2.0315) band:", band(3.4445, -4.7750, 2.0315))
